// G8.03.T3 — normaliza conversation_status_changed e gera Idempotency-Key
const item = $input.item.json;
const body = item.body || item || {};
const event = body.event || 'conversation_status_changed';
const conv = body.conversation || {};
const status = body.status || conv.status || 'unknown';
const convId = conv.id || body.id || '0';
const assignee = body.assignee || (conv.meta && conv.meta.assignee) || conv.assignee || null;
const eventId = String(body.id || `${convId}-${status}-${Date.now()}`);
const idem = `cw-status-${eventId}`;

return {
  json: {
    event,
    id: eventId,
    status,
    conversation: { id: convId, status },
    assignee,
    idempotency_key: idem,
    // destino API (env override em prod)
    api_url: $env.CARTORIO_API_BASE || 'https://api.2notasudi.com.br',
    path: '/api/v1/webhooks/chatwoot'
  }
};
